 decisions=[dict(at='F10',question='这是有效的新知识缺口吗？',yes='确认资料来源、分派维护 → T16',no='合并或撤销并保留原因；此入口待实现',refs=['F10','T16']),dict(at='T16',question='对应业务文档已经审核生效吗？',yes='完成缺口并回查原事项 → F14 / T05',no='保持维护中，客户事项继续跟进 → T09',refs=['T16','F14','T05','T09'])],
