def enrich(tasks,roles,stages):
    expanded=deepcopy(tasks)
    for row in EXTRA_TASKS:
        id,role,stage,title,trigger,steps,done,exception,view,availability=row
        expanded.append(dict(id=id,role=role,stage=stage,title=title,trigger=trigger,steps=steps,done=done,exception=exception,view=view,availability=availability))
    for t in expanded:
        detail=DETAILS.get(t['id'])
        if detail:
            inputs,output,deps,support,gap=detail
        else:
            inputs=[s for s in t['steps'][:1]];output=t['done'];deps=[];support=t['exception'];gap=t['exception']
        t.update(inputs=inputs,output=output,depends_on=deps,current_support=support,gap=gap,
            scenario_ids=[s['id'] for s in SCENARIOS if t['id'] in s['task_ids']],
            source='本地试用与自动化验收' if t['availability']=='local' else '基于当前能力的业务推演；待真实业务人员确认',
            frequency='尚无真实业务使用频率样本',verification='以任务完成标准进行本地验收；不证明真实客户问题已解决' if t['availability']=='local' else '先访谈/观察业务场景，再补流程与验收样例',
            acceptance=[t['done'],'异常发生时保留原记录，并能说明下一步由谁处理'])
        if t['id'] in PRIORITY and t['availability']!='local':
            p,impact,reason,validation=PRIORITY[t['id']]
            t.update(priority=p,impact=impact,priority_reason=reason,validation=validation,priority_status='建议，待业务验证')
        else:t.update(priority='baseline',impact='当前本地流程基线',priority_reason='已具备本地能力，保留回归检查',validation='观察实际业务使用后再判断改进优先级',priority_status='本地已验收，不代表生产可用')
    role_data=[dict(r,goal=ROLE_GOALS[r['id']][1],deliverable=ROLE_GOALS[r['id']][2]) for r in roles]
    stage_data=[dict(id=i,name=name,goal=STAGE_DETAILS[i][0],inputs=STAGE_DETAILS[i][1],output=STAGE_DETAILS[i][2],exception=STAGE_DETAILS[i][3],task_ids=[t['id'] for t in expanded if t['stage']==i]) for i,name in enumerate(stages)]
    return dict(tasks=expanded,roles=role_data,stage_details=stage_data,scenarios=SCENARIOS,
        goal='在承诺时间内，让客户问题有明确处理结果，并留下能够交接和核对的记录。',
        audience='售后服务场景的当班客服、接班同事、主管与知识维护人员',
        research=dict(basis='本机历史订单试用、两名成员交接演练和自动化检查；新增缺口来自业务推演',limits='尚未完成真实客服访谈或生产观察；频率、损失、渠道、服务承诺与优先级仍需验证',questions=['你开始当班时怎样决定先处理哪一单？','什么情况下必须追补材料，通常卡在哪里？','交给同事后，怎样确认对方真的接手？','你们认定结案的条件是什么，是否需要客户确认？','哪些问题必须在外部系统完成，失败后谁负责？','每周主管根据哪些数据做什么决定？']),
        priority_guide={'P1':'先验证业务闭环或正式使用前置条件','P2':'随后验证协作、证据与承诺的一致性','P3':'核心流程验证后再评估分析深化','baseline':'当前本地可用基线；继续观察与回归'},
        roadmap=[dict(title='当前基线',description='本地受理、核对、回复准备、共享交接、期限跟进与知识维护',task_ids=['T01','T02','T03','T05','T08','T09','T10','T16']),dict(title='继续验证的中断与责任',description='失败恢复与接手确认已补齐本地流程；继续观察，并验证客户确认的退出条件',task_ids=['F06','F07','F05']),dict(title='正式业务接入前',description='确认渠道、平台与身份边界，再安排真实执行与回执；不是已承诺排期',task_ids=['F01','F02','F12'])],
        metrics=[dict(name='结案结果',definition='本地结案记录与客户确认分开；实际解决需客户或业务平台证据',status='本地结案已有，客户确认待接入',tasks=['T10','F05']),dict(name='交接完成',definition='分派给某人，且对方确认接手；不能仅统计负责人字段改变',status='分派、接受/退回、待接手队列均已本地支持；自动升级待补',tasks=['T08','F07']),dict(name='承诺履行',definition='有负责人、约定下一步及期限；承诺时段和例外规则需业务定义',status='本地期限已有，承诺规则待验证',tasks=['T09','F11']),dict(name='知识补齐',definition='有可靠来源且审核生效，受影响事项已重新核对',status='文档生效已有，事项回查待完善',tasks=['T16','F14'])])
